mapper.select:
SELECT id, account_id, card_id, external_key, transaction_date,
       transaction_time, transaction_type, transaction_region,
       amount, balance_after, merchant_name, memo, category_id
FROM transactions
WHERE card_id = #{cardId}
  AND transaction_date >= #{startDate}
  AND transaction_date <= #{endDate}
  AND is_deleted = 0
ORDER BY transaction_date DESC, transaction_time DESC, id DESC
